whey-pro-win-2-2-lb","verificacion_fuente":"url_producto"},{"fuente_clave":"vip_local_2026:whey-matrix-mezcla-proteica","nombre":"Whey Matrix (mezcla proteica)","categoria":"Suplementos deportivos","tipo_producto":"suplemento_marca","marca":"Sportlab","porcion_base":36,"kcal":140,"prot":25,"carb":7,"grasa":2,"fibra":0,"azucares":3,"sodio":0.064,"pais_origen":"Nacional (Chile)","fuente_datos":"Ficha pública del producto o distribuidor","fuente_url":"https://allnutrition.cl/products/whey-matrix-5-lb","verificacion_fuente":"url_producto"},{"fuente_clave":"vip_local_2026:creatina-pro","nombre":"Creatina PRO","categoria":"Suplementos deportivos","tipo_producto":"suplemento_marca","marca":"Sportlab","porcion_base":5,"kcal":0,"prot":0,"carb":0,"grasa":0,"fibra":0,"azucares":0,"sodio":0,"pais_origen":"Nacional (Chile)","fuente_datos":"Ficha pública del producto o distribuidor","fuente_url":"https://allnutrition.cl/products/creatine-pro-300g","verificacion_fuente":"url_producto"}]$vip_nutricion$::jsonb) as fila(
    fuente_clave text,
    nombre text,
    categoria text,
    tipo_producto text,
    marca text,
    porcion_base numeric,
    kcal numeric,
    prot numeric,
    carb numeric,
    grasa numeric,
    fibra numeric,
    azucares numeric,
    sodio numeric,
    pais_origen text,
    fuente_datos text,
    fuente_url text,
    verificacion_fuente text
  )
), candidatos as (
  select fila.*
  from fuente fila
  where not exists (
    select 1
    from public.alimentos actual
    where actual.creado_por is null
      and translate(
        lower(regexp_replace(trim(actual.nombre), '\s+', ' ', 'g')),
        'áàäâéèëêíìïîóòöôúùüûñ',
        'aaaaeeeeiiiioooouuuun'
      ) = translate(
        lower(regexp_replace(trim(fila.nombre), '\s+', ' ', 'g')),
        'áàäâéèëêíìïîóòöôúùüûñ',
        'aaaaeeeeiiiioooouuuun'
      )
  )
)
insert into public.alimentos (
  nombre, categoria, porcion_base, unidad, kcal, prot, carb, grasa,
  activo, medida_nombre, medida_gramos, creado_por, aprobado, origen,
  off_id, marca, imagen_url, fibra, azucares, sodio, tipo_producto,
  pais_origen, fuente_datos, fuente_url, fuente_clave, verificacion_fuente
)
select
  nombre, categoria, porcion_base, 'g', kcal, prot, carb, grasa,
  true, null, null, null, true, 'catalogo', null, marca, null, fibra,
  azucares, sodio, tipo_producto, pais_origen, fuente_datos, fuente_url,
  fuente_clave, verificacion_fuente
from candidatos
on conflict do nothing;

comment on column public.alimentos.fuente_datos is 'Descripción de la procedencia nutricional; no implica validación clínica.';
comment on column public.alimentos.fuente_url is 'URL puntual del producto cuando la fuente la entrega.';
comment on column public.alimentos.verificacion_fuente is 'Nivel de trazabilidad disponible para mostrar y auditar el dato.';
